function ActivityCrisisUtils.HandleEntryData(entryData)
    if isNull(entryData) or table.count(entryData) <= 0 then
        return {}
    end
    local data = {}
    for i, j in pairs(entryData) do
        for k, v in pairs(j) do
            local vo = ActivityCrisisUtils.GetCrisisEventEntryEffectVo(v)
            if not isNull(vo) and ActivityCrisisUtils.TeamType[vo.type] then
                if isNull(data[vo.type]) then
                    data[vo.type] = {}
                end
                ---类型为2和6的时候   直接使用大的ID的 替换小的ID
                if vo.type == ActivityCrisisUtils.EntryType.BattleCondition
                        or vo.type == ActivityCrisisUtils.EntryType.AmendTeamNumber
                        or vo.type == ActivityCrisisUtils.EntryType.Round then
                    if table.count(data[vo.type]) > 0 then
                        if vo.refId >= data[vo.type][1].refId then
                            data[vo.type][1] = vo
                        end
                    else
                        table.insert(data[vo.type],vo)
                    end
                elseif vo.type == ActivityCrisisUtils.EntryType.CatLimit then
                    table.insert(data[vo.type],vo)
                end
            end
        end
    end
    return data
end

---获取最大回合数  回合数也会受到词条影响
function ActivityCrisisUtils.GetMaxRoundMember()
    local entryData = ActivityCrisisUtils.GetActivityCrisisMgr():GetEntryData()

    if isNull(entryData) then
        return nil
    end

    if isNotNull(entryData[ActivityCrisisUtils.EntryType.Round]) then
        return checkNumber(entryData[ActivityCrisisUtils.EntryType.Round][1].param)
    end

    return nil
end

function ActivityCrisisUtils.EnterBattleTeam(questId,buffData)
    local activityData = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityData()
   --[[ local TeamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    TeamComponent:CleanTeamTabBySystemId(tostring(activityData.type))]]
    local levelVo = ActivityCrisisUtils.GetCrisisEventLevelVo(questId)
    local entryData = ActivityCrisisUtils.HandleEntryData(buffData)
    ActivityCrisisUtils.GetActivityCrisisMgr():SaveEntryData(entryData)

    if not isNull(entryData) and not isNull(entryData[ActivityCrisisUtils.EntryType.BattleCondition]) then
        levelVo.roleRestrictions = entryData[ActivityCrisisUtils.EntryType.BattleCondition][1].param
    else
        levelVo.roleRestrictions = 0
    end

    if not isNull(entryData) and not isNull(entryData[ActivityCrisisUtils.EntryType.AmendTeamNumber]) then
        levelVo.roleNun = entryData[ActivityCrisisUtils.EntryType.AmendTeamNumber][1].param
    else
        levelVo.roleNun = 4
    end

    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIFightTeamChoose,
        parameters = {
            activityUuid = activityData.id,
            levelId = questId,
            buffGroups = table.serialize(buffData),
            teamIndex = 1
        }
    }, {
        { id = Constants.UITypeIds.ActivityCrisisContractLevelListDialog }
    })

end

