---@param cirPos table 圆的横坐标
---@return table 返回坐标结构体
function ActivityCrisisUtils.GetCirePosition(cirPos)
    local x = checkInt( cirPos[1])
    local y = checkInt(cirPos[2]) 
    local cX = (x- 0.5) * WC + (x-1) *WL 
    local cY = (y * H) + BH 
    return { x = cX , y = cY }
end

--- func desc
---@param startPos number 起始坐标
---@param endPos number 结束坐标
---@return table 返回结构
function ActivityCrisisUtils.GetLineStructure(startPos , endPos)
    local middleStruct = {
        x = 0 ,
        y = 0 ,
        width = 0, 
        high  =  0,
        isSprite9 = false
    }
    if isNull(endPos) or table.count(endPos) == 0 then
        local x = startPos[1]
        local y = startPos[2]
        middleStruct.x = (x - 0.5) * WL + WC
        middleStruct.y = (y * H) + BH 
    end
    if table.count(endPos) > 0 then
        -- 线横向坐标间距
        local disX = math.abs((startPos[1] - endPos[1])) 
        -- 线纵向坐标间距
        local disY = math.abs(endPos[2] - startPos[2])
        -- 线起始横坐标
        local startX = math.min(startPos[1], endPos[1]) 
        -- 线起始纵坐标
        local startY = math.min(startPos[2], endPos[2])
        -- 间距长度
        local width = disX * (WL + WC)
        -- 间距高度
        local high = disY *  H 
        -- 横向坐标中点等于 横向坐标的间距的一半 加上起始点的位置
        local cX = width / 2 + (startX - 0.5 ) * WL + (startX * WC)
        -- 纵向坐标中点等于 纵向坐标的间距的一半 加上起始点的位置
        local cY = high / 2 + startY * H +  BH
        middleStruct.x = cX
        middleStruct.y = cY
        if disX > 0  then
            middleStruct.isSprite9 = true 
            middleStruct.width =  width
        elseif disY > 0 then
            middleStruct.isSprite9 = true 
            middleStruct.high =  high
        end
        return middleStruct
    end
end
---@param positions table or圆坐标数组
---@return table 返回原线结构题
function ActivityCrisisUtils.GetOrCircleLineStruct(positions)
    local cirLineStruct = {
        x = 0, 
        y = 0, 
        high = 0 , -- 线圈的索引顺序
    }
    local minY = positions[1][2]
    local maxY = positions[1][2]
    for k, pos in pairs(positions) do
        if minY > pos[2] then
            minY = pos[2]
        end
        if maxY < pos[2] then
            maxY = pos[2]
        end
    end
    local cY =  ((maxY + minY) / 2  * H) + BH 
    local x = positions[1][1]
    local cX = (x- 0.5) * WC + (x-1) *WL 
    cirLineStruct.x = cX
    cirLineStruct.y = cY
    local index =  ((maxY - minY) + 2) * H 
    cirLineStruct.high = index
    return cirLineStruct
end

---@param questGroupVos CrisisEventEntryPosVo[]
function ActivityCrisisUtils.GetMaxHigh(questGroupVos)
    local maxY = 0 
    for k, v in ipairs(questGroupVos) do
        if checkInt(v.siteType) == 1 then
            local Y = checkInt(v.tagLoc[2])
            if Y > maxY then
                maxY = Y
            end 
        end
    end
    local cY = ((maxY + 1) * H) + BH + TH
    return cY
end  

--- 词条是否限制猫球
function ActivityCrisisUtils.IsEntryLimitCat(data,type)
    if isNull(data) or isNull(data[ActivityCrisisUtils.EntryType.CatLimit]) then
        return false
    end

    for i, v in pairs(data[ActivityCrisisUtils.EntryType.CatLimit]) do
        if v.param == type then
            return true
        end
    end

    return false
end

function ActivityCrisisUtils.GetHistoryScore(questId)
    local levelVo = ActivityCrisisUtils.GetCrisisEventLevelVo(questId)
    local dojo = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityDojo()
    if levelVo.type == ActivityCrisisUtils.LevelType.Normal then
        return checkNumber(dojo:GetNormalQuestData().score)
    else
        local data = dojo:GetRotationQuest()
        for i, v in pairs(data) do
            if checkNumber(v.questId) == checkNumber(questId) then
                return checkNumber(v.score)
            end
        end
    end
    return 0
end

function ActivityCrisisUtils.GetTaskLimitTimeByQuestId(questId)
    local levelVo = ActivityCrisisUtils.GetCrisisEventLevelVo(questId)
    local dojo = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityDojo()
    local taskData
    if levelVo.type == ActivityCrisisUtils.TaskType.Rotation then
        taskData = dojo:GetRotationQuest()
    else
        taskData = dojo:GetNormalQuest()
    end

    for i, v in pairs(taskData) do
        if checkNumber(v.questId) == questId then
            local limitCountDown = checkNumber(v.limitCountdown)
            local remainTime = limitCountDown - os.time()
            if limitCountDown > 0 and remainTime > 0 then
               return remainTime
            end
            break
        end
    end
    return 0
end


return ActivityCrisisUtils